import pulp
import networkx as nx
import random

def gamma_t_ilp(G):
    prob = pulp.LpProblem('TDS', pulp.LpMinimize)
    nodes = list(G.nodes())
    x = {v: pulp.LpVariable(f'x_{v}', cat=pulp.LpBinary) for v in nodes}
    prob += pulp.lpSum(x.values())
    for v in nodes:
        prob += pulp.lpSum(x[u] for u in G.neighbors(v)) >= 1
    prob.solve(pulp.PULP_CBC_CMD(msg=False))
    return int(pulp.value(prob.objective))

# Test on various graph families:
# 1. Trees of various types (spiders, caterpillars, combs, long paths with whiskers)
print('Testing specific tree families...')
for k in range(1, 15):
    # Path of length 4k+r
    for r in range(4):
        P = nx.path_graph(4*k + r)
        if len(P) >= 2:
            rad = nx.radius(P)
            gt = gamma_t_ilp(P)
            if rad > gt:
                print(f'Counterexample Path! n={len(P)}, rad={rad}, gt={gt}')

# 2. Random trees up to n=50
for n in range(5, 51, 5):
    for _ in range(50):
        T = nx.random_labeled_tree(n)
        rad = nx.radius(T)
        gt = gamma_t_ilp(T)
        if rad > gt:
            print(f'Counterexample Tree! n={n}, rad={rad}, gt={gt}')
            exit(0)
print('Random trees up to 50: no counterexample!')
